BOOL IsPalindrome(char *str)
{
    int len = strlen(str) - 1;
    int i = 0;
    while (i < len) {
        if (str[i] != str[len]) {
            break;
        }
        i++;
        len--;
    }

    if (i >= len) {
        return TRUE;
    }

    return FALSE;
}
