VRP_JOB_ID HQOS_CreateJob(const HqosJob *jobData, void *pThis)
{
    FEI_JOB_PROC_FUNC_MAP_S jobFunc = { jobData->jobTypeId, jobData->jobName, 1, FEI_JOB_Create, FEI_JOB_DeleteByType,
        jobData->jobProc };
    u_int32_t funcMapNum = 1;
    u_int32_t ret = FEI_JOB_DynInitJobProcFuncTbl(&jobFunc, &funcMapNum, pThis);
    if (ret != HQOS_OK) {
        return NULL;
    }
    VRP_JOB_ID jobId = NULL;
    ret = FEI_JOB_Create(jobData->jobTypeId, jobData->jobName, jobData->userData, &jobId, pThis);
    if (ret != HQOS_OK) {
        return NULL;
    }
    return jobId;
}






